def extract(g, rmax, rmin=0):
    from collections import deque
    seen=set(); res=[]
    for r in range(rmin,rmax):
        for c in range(len(g[0])):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if rmin<=ny<rmax and 0<=nx<len(g[0]) and g[ny][nx]==col and (ny,nx) not in seen:
                                seen.add((ny,nx)); q.append((ny,nx))
                ys=[y for y,x in cells]; xs=[x for y,x in cells]
                res.append(dict(col=col,top=min(ys),left=min(xs),
                                pat=pat(g,min(ys),min(xs)),n=len(cells)))
    return res
